        meaning: {
          kn: "ಇದು ಗಣೇಶನ ಅತ್ಯಂತ ಜನಪ್ರಿಯ ಹನ್ನೆರಡು ಪವಿತ್ರ ನಾಮಗಳ ಸ್ತೋತ್ರ. ಯಾವುದೇ ಹೊಸ ಕೆಲಸ, ವಿದ್ಯಾರಂಭ, ವಿವಾಹ, ಪ್ರಯಾಣ ಅಥವಾ ಕಷ್ಟದ ಸಮಯದಲ್ಲಿ ಇದನ್ನು ಪಠಿಸಿದರೆ ವಿಘ್ನಗಳು ದೂರವಾಗುತ್ತವೆ ಎಂದು ನಂಬಿಕೆ. ಪ್ರತಿದಿನ ಬೆಳಿಗ್ಗೆ ಪಠಿಸುವುದರಿಂದ ಬುದ್ಧಿ, ಏಕಾಗ್ರತೆ ಮತ್ತು ಧೈರ್ಯ ವೃದ್ಧಿಸುತ್ತದೆ.",
          sa: "इदं गणेशस्य द्वादशनामस्तोत्रं सर्वविघ्ननाशकम्। विद्यारम्भे विवाहे यात्रायां सङ्कटे च पठनात् विघ्नाः न भवन्ति। नित्यं प्रातः पठनेन बुद्धिः स्मृतिः साहसं च वर्धते।",
          ta: "இது கணேசரின் மிகவும் பிரபலமான பன்னிரண்டு புனித நாமங்களின் ஸ்தோத்திரம். கல்வி தொடக்கம், திருமணம், பயணம், போர் அல்லது இடர் காலங்களில் இதைச் சொன்னால் இடையூறுகள் நீங்கும் என நம்பப்படுகிறது. தினமும் காலையில் ஓதுவது புத்தி கூர்மையையும் தைரியத்தையும் அளிக்கும்.",
          ml: "ഗണപതിയുടെ ഏറ്റവും പ്രശസ്തമായ പന്ത്രണ്ട് പുണ്യനാമങ്ങളുടെ സ്തോത്രമാണിത്. വിദ്യാരംഭം, വിവാഹം, യാത്ര, യുദ്ധം അല്ലെങ്കിൽ ആപത്ഘട്ടങ്ങളിൽ ഇത് ജപിച്ചാൽ വിഘ്നങ്ങൾ അകലുമെന്നാണ് വിശ്വാസം. ദിവസവും രാവിലെ ജപിക്കുന്നത് ബുദ്ധിയും ധൈര്യവും വർദ്ധിപ്പിക്കും.",
          te: "ఇది గణేశుని అత్యంత ప్రసిద్ధమైన పన్నెండు పవిత్ర నామాల స్తోత్రం. విద్యారంభం, వివాహం, ప్రయాణం, యుద్ధం లేదా కష్టకాలంలో దీనిని పఠిస్తే విఘ్నాలు తొలగిపోతాయని నమ్మకం. ప్రతిరోజు ఉదయం పఠించడం వల్ల బుద్ధి, జ్ఞాపకశక్తి, ధైర్యం పెరుగుతాయి."
        }
