        meaning: {
          kn: "ಮಗು, ಆದಿಶಂಕರಾಚಾರ್ಯರು 'ನಮಃ ಶಿವಾಯ' ಎಂಬ ಐದು ಅಕ್ಷರಗಳಿಗೆ ಒಂದೊಂದೇ ಶ್ಲೋಕ ಬರೆದಿದ್ದಾರೆ. ಇಲ್ಲಿ 'ನ' ಅಕ್ಷರದ ಶ್ಲೋಕ ಕೊಟ್ಟಿದ್ದೇವೆ - ಹಾವಿನ ಹಾರ ಧರಿಸಿದ, ಮೂರು ಕಣ್ಣುಳ್ಳ ಶಿವನನ್ನು ಇದು ವರ್ಣಿಸುತ್ತದೆ.",
          sa: "वत्स, आदिशङ्कराचार्यैः 'नमः शिवाय' इति पञ्चाक्षराणां प्रत्येकाक्षराय एकैकं श्लोकं रचितम्। अत्र 'न' अक्षरस्य श्लोकः दत्तः - सर्पहारं त्रिनेत्रं शिवं वर्णयन्।",
          ta: "குழந்தாய், ஆதி சங்கராச்சாரியார் 'நமஃ சிவாய' என்ற ஐந்து எழுத்துகளுக்கும் ஒவ்வொரு ஸ்லோகம் எழுதியுள்ளார். இங்கு 'ந' எழுத்தின் ஸ்லோகம் தரப்பட்டுள்ளது - பாம்பு மாலை அணிந்த, மூன்று கண்களுடைய சிவனை இது வர்ணிக்கிறது.",
          ml: "കുഞ്ഞേ, ആദിശങ്കരാചാര്യർ 'നമഃ ശിവായ' എന്ന അഞ്ച് അക്ഷരങ്ങൾക്കും ഓരോ ശ്ലോകം വീതം എഴുതിയിട്ടുണ്ട്. ഇവിടെ 'ന' എന്ന അക്ഷരത്തിന്റെ ശ്ലോകം നൽകിയിരിക്കുന്നു - പാമ്പ് മാല ധരിച്ച, മൂന്ന് കണ്ണുള്ള ശിവനെ ഇത് വർണ്ണിക്കുന്നു.",
          te: "పాపా, ఆదిశంకరాచార్యులు 'నమః శివాయ' అనే ఐదు అక్షరాలకు ఒక్కొక్క శ్లోకం రాశారు. ఇక్కడ 'న' అక్షరం శ్లోకం ఇచ్చాము - పాముల హారం ధరించిన, మూడు కళ్ళు కలిగిన శివుడిని ఇది వర్ణిస్తుంది."
        }
