          sa: "एतानि विष्णोः प्रियनामानि। 'जगन्नाथः' इत्यर्थः 'सर्वजगतः स्वामी', 'भक्तवत्सलः' इत्यर्थः 'भक्तान् शिशुवत् स्नेहयन्'। बालाः एतानि सरलनामानि शिक्षितुं शक्नुवन्ति।",
          ta: "இவை விஷ்ணுவின் அன்பான பெயர்கள். 'ஜகந்நாதன்' என்றால் 'உலகம் முழுவதற்கும் அதிபதி', 'பக்தவத்சலன்' என்றால் 'பக்தர்களை குழந்தை போல் நேசிப்பவர்' என்று பொருள். குழந்தைகள் இந்த எளிய பெயர்களைக் கற்கலாம்.",
          ml: "ഇവ വിഷ്ണുവിന്റെ പ്രിയപ്പെട്ട പേരുകളാണ്. 'ജഗന്നാഥൻ' എന്നാൽ 'ലോകം മുഴുവന്റെയും നാഥൻ', 'ഭക്തവത്സലൻ' എന്നാൽ 'ഭക്തരെ കുഞ്ഞിനെപ്പോലെ സ്നേഹിക്കുന്നവൻ' എന്നർത്ഥം. കുട്ടികൾക്ക് ഈ എളുപ്പ പേരുകൾ പഠിക്കാം.",
