          ml: "ദുർഗ്ഗാ സപ്തശതി (ദേവീ മാഹാത്മ്യം) മാർക്കണ്ഡേയ പുരാണത്തിന്റെ ഭാഗമാണ്, 700 ശ്ലോകങ്ങളുള്ള 13 അധ്യായങ്ങളിൽ ദേവിയുടെ മഹിമ വർണ്ണിക്കുന്നു. മധു-കൈടഭൻ, മഹിഷാസുരൻ, ശുംഭ-നിശുംഭൻ എന്നീ മൂന്ന് പ്രധാന അസുര സംഹാര കഥകൾ ഇതിലുണ്ട്. നവരാത്രിയിലെ ഒൻപത് ദിവസങ്ങളിൽ പൂർണ്ണപാഠം ജപിക്കുന്നത് പാരമ്പര്യമാണ്; ഗ്രന്ഥം ദീർഘമായതിനാൽ ഇവിടെ അധ്യായസംഗ്രഹം നൽകിയിരിക്കുന്നു.",
          te: "దుర్గా సప్తశతి (దేవీ మాహాత్మ్యం) మార్కండేయ పురాణంలో భాగం, 700 శ్లోకాలతో కూడిన 13 అధ్యాయాలలో దేవి మహిమను వర్ణిస్తుంది. మధు-కైటభ, మహిషాసుర, శుంభ-నిశుంభ అనే మూడు ప్రధాన రాక్షస సంహార కథలు ఇందులో ఉన్నాయి. నవరాత్రి తొమ్మిది రోజులలో పూర్తి పాఠం పఠించడం సంప్రదాయం; గ్రంథం చాలా పొడవుగా ఉన్నందున ఇక్కడ అధ్యాయాల సారాంశం ఇవ్వబడింది."
