          ta: "ஆதி சங்கராச்சாரியார் இயற்றிய இந்த எட்டு பாடல்களின் ஸ்தோத்திரம் ஸ்ரீகிருஷ்ணனின் பல்வேறு நாமங்களையும் லீலைகளையும் நினைவுகூர்கிறது. ஒவ்வொரு பாடலிலும் கிருஷ்ணனின் பல நாமங்கள் தொடுக்கப்பட்டு பக்தி பாவத்துடன் பாட வடிவமைக்கப்பட்டுள்ளது. தினமும் ஓதுவதால் மனதிற்கு ஆனந்தம், பக்தி, அமைதி கிடைக்கும்.",
          ml: "ആദിശങ്കരാചാര്യർ രചിച്ച ഈ എട്ട് പദ്യങ്ങളുടെ സ്തോത്രം ശ്രീകൃഷ്ണന്റെ വിവിധ നാമങ്ങളും ലീലകളും സ്മരിക്കുന്നു. ഓരോ പദ്യത്തിലും കൃഷ്ണന്റെ പല നാമങ്ങൾ കോർത്തിണക്കി ഭക്തിഭാവത്തോടെ പാടാൻ രചിച്ചതാണ്. ദിവസവും ജപിക്കുന്നത് മനസ്സിന് ആനന്ദവും ഭക്തിയും ശാന്തിയും നൽകും.",
          te: "ఆదిశంకరాచార్యులు రచించిన ఈ ఎనిమిది పద్యాల స్తోత్రం శ్రీకృష్ణుని వివిధ నామాలను, లీలలను స్మరిస్తుంది. ప్రతి పద్యంలోనూ కృష్ణుని అనేక నామాలను గుదిగుచ్చి భక్తిభావంతో పాడేలా రచించారు. దీనిని ప్రతిరోజూ పఠించడం వల్ల మనసుకు ఆనందం, భక్తి, శాంతి లభిస్తాయి."
