          ta: "திருப்பதி கோவிலில் உண்டியலில் காணிக்கை செலுத்தும்போது, முடி இறக்கும்போது, சிறப்பு நேரங்களில் பக்தர்கள் ஒன்றாக முழங்கும் 'கோவிந்தா கோவிந்தா' நாம கோஷம் இது. இதை ஜபிப்பது அல்லது முழங்குவது மனதில் பக்தி உணர்வை நிரப்பி விருப்பங்களை நிறைவேற்றும் என நம்பப்படுகிறது.",
